1410   * Returns 0 in case of success, -1 in case of failure
  1411   */
  1412  static int
  1413  xmlXIncludeLoadDoc(xmlXIncludeCtxtPtr ctxt, const xmlChar *url, int nr) {
  1414      xmlDocPtr doc;
  1415      xmlURIPtr uri;
  1416      xmlChar *URL;
  1417      xmlChar *fragment = NULL;
  1418      int i = 0;
  1419  #ifdef LIBXML_XPTR_ENABLED
  1420      int saveFlags;
  1421  #endif
  1422
  1423  #ifdef DEBUG_XINCLUDE
  1424      xmlGenericError(xmlGenericErrorContext, "Loading doc %s:%d\n", url, nr);
  1425  #endif
  1426      /*
  1427       * Check the URL and remove any fragment identifier
  1428       */
  1429      uri = xmlParseURI((const char *)url);
  1430      if (uri == NULL) {
  1431          xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  1432                         XML_XINCLUDE_HREF_URI,
  1433                         "invalid value URI %s\n", url);
  1434          return(-1);
  1435      }
  1436      if (uri->fragment != NULL) {
  1437          fragment = (xmlChar *) uri->fragment;
  1438          uri->fragment = NULL;
  1439      }
  1440      if ((ctxt->incTab != NULL) && (ctxt->incTab[nr] != NULL) &&
  1441          (ctxt->incTab[nr]->fragment != NULL)) {
  1442          if (fragment != NULL) xmlFree(fragment);
  1443          fragment = xmlStrdup(ctxt->incTab[nr]->fragment);
  1444      }
  1445      URL = xmlSaveUri(uri);
  1446      xmlFreeURI(uri);
  1447      if (URL == NULL) {
  1448          if (ctxt->incTab != NULL)
  1449              xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  1450                             XML_XINCLUDE_HREF_URI,
  1451                             "invalid value URI %s\n", url);
  1452          else
  1453              xmlXIncludeErr(ctxt, NULL,
  1454                             XML_XINCLUDE_HREF_URI,
  1455                             "invalid value URI %s\n", url);
  1456          if (fragment != NULL)
  1457              xmlFree(fragment);
  1458          return(-1);
  1459      }
  1460
  1461      /*
  1462       * Handling of references to the local document are done
  1463       * directly through ctxt->doc.
  1464       */
  1465      if ((URL[0] == 0) || (URL[0] == '#') ||
  1466          ((ctxt->doc != NULL) && (xmlStrEqual(URL, ctxt->doc->URL)))) {
  1467          doc = ctxt->doc;
  1468          goto loaded;
  1469      }
  1470
  1471      /*
  1472       * Prevent reloading twice the document.
  1473       */
  1474      for (i = 0; i < ctxt->incNr; i++) {
  1475          if ((xmlStrEqual(URL, ctxt->incTab[i]->URI)) &&
  1476              (ctxt->incTab[i]->doc != NULL)) {
  1477              doc = ctxt->incTab[i]->doc;
  1478  #ifdef DEBUG_XINCLUDE
  1479              printf("Already loaded %s\n", URL);
  1480  #endif
  1481              goto loaded;
  1482          }
  1483      }
  1484
  1485      /*
  1486       * Load it.
  1487       */
  1488  #ifdef DEBUG_XINCLUDE
  1489      printf("loading %s\n", URL);
  1490  #endif
  1491  #ifdef LIBXML_XPTR_ENABLED
  1492      /*
  1493       * If this is an XPointer evaluation, we want to assure that
  1494       * all entities have been resolved prior to processing the
  1495       * referenced document
  1496       */
  1497      saveFlags = ctxt->parseFlags;
  1498      if (fragment != NULL) {     /* if this is an XPointer eval */
  1499          ctxt->parseFlags |= XML_PARSE_NOENT;
  1500      }
  1501  #endif
  1502
  1503      doc = xmlXIncludeParseFile(ctxt, (const char *)URL);
  1504  #ifdef LIBXML_XPTR_ENABLED
  1505      ctxt->parseFlags = saveFlags;
  1506  #endif
  1507      if (doc == NULL) {
  1508          xmlFree(URL);
  1509          if (fragment != NULL)
  1510              xmlFree(fragment);
  1511          return(-1);
  1512      }
  1513      ctxt->incTab[nr]->doc = doc;
  1514      /*
  1515       * It's possible that the requested URL has been mapped to a
  1516       * completely different location (e.g. through a catalog entry).
  1517       * To check for this, we compare the URL with that of the doc
  1518       * and change it if they disagree (bug 146988).
  1519       */
  1520     if (!xmlStrEqual(URL, doc->URL)) {
  1521         xmlFree(URL);
  1522         URL = xmlStrdup(doc->URL);
  1523     }
  1524      for (i = nr + 1; i < ctxt->incNr; i++) {
  1525          if (xmlStrEqual(URL, ctxt->incTab[i]->URI)) {
  1526              ctxt->incTab[nr]->count++;
  1527  #ifdef DEBUG_XINCLUDE
  1528              printf("Increasing %s count since reused\n", URL);
  1529  #endif
  1530              break;
  1531          }
  1532      }
  1533
  1534      /*
  1535       * Make sure we have all entities fixed up
  1536       */
  1537      xmlXIncludeMergeEntities(ctxt, ctxt->doc, doc);
  1538
  1539      /*
  1540       * We don't need the DTD anymore, free up space
  1541      if (doc->intSubset != NULL) {
  1542          xmlUnlinkNode((xmlNodePtr) doc->intSubset);
  1543          xmlFreeNode((xmlNodePtr) doc->intSubset);
  1544          doc->intSubset = NULL;
  1545      }
  1546      if (doc->extSubset != NULL) {
  1547          xmlUnlinkNode((xmlNodePtr) doc->extSubset);
  1548          xmlFreeNode((xmlNodePtr) doc->extSubset);
  1549          doc->extSubset = NULL;
  1550      }
  1551       */
  1552      xmlXIncludeRecurseDoc(ctxt, doc, URL);
  1553
  1554  loaded:
  1555      if (fragment == NULL) {
  1556          /*
  1557           * Add the top children list as the replacement copy.
  1558           */
  1559          ctxt->incTab[nr]->inc = xmlXIncludeCopyNodeList(ctxt, ctxt->doc,
  1560                                                          doc, doc->children);
  1561      }
  1562  #ifdef LIBXML_XPTR_ENABLED
  1563      else {
  1564          /*
  1565           * Computes the XPointer expression and make a copy used
  1566           * as the replacement copy.
  1567           */
  1568          xmlXPathObjectPtr xptr;
  1569          xmlXPathContextPtr xptrctxt;
  1570          xmlNodeSetPtr set;
  1571
  1572          xptrctxt = xmlXPtrNewContext(doc, NULL, NULL);
  1573          if (xptrctxt == NULL) {
  1574              xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  1575                             XML_XINCLUDE_XPTR_FAILED,
  1576                             "could not create XPointer context\n", NULL);
  1577              xmlFree(URL);
  1578              xmlFree(fragment);
  1579              return(-1);
  1580          }
  1581          xptr = xmlXPtrEval(fragment, xptrctxt);
  1582          if (xptr == NULL) {
  1583              xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  1584                             XML_XINCLUDE_XPTR_FAILED,
  1585                             "XPointer evaluation failed: #%s\n",
  1586                             fragment);
  1587              xmlXPathFreeContext(xptrctxt);
  1588              xmlFree(URL);
  1589              xmlFree(fragment);
  1590              return(-1);
  1591          }
  1592          switch (xptr->type) {
  1593              case XPATH_UNDEFINED:
  1594              case XPATH_BOOLEAN:
  1595              case XPATH_NUMBER:
  1596              case XPATH_STRING:
  1597              case XPATH_POINT:
  1598              case XPATH_USERS:
  1599              case XPATH_XSLT_TREE:
  1600                  xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  1601                                 XML_XINCLUDE_XPTR_RESULT,
  1602                                 "XPointer is not a range: #%s\n",
  1603                                 fragment);
  1604                  xmlXPathFreeObject(xptr);
  1605                  xmlXPathFreeContext(xptrctxt);
  1606                  xmlFree(URL);
  1607                  xmlFree(fragment);
  1608                  return(-1);
  1609              case XPATH_NODESET:
  1610                  if ((xptr->nodesetval == NULL) ||
  1611                      (xptr->nodesetval->nodeNr <= 0)) {
  1612                      xmlXPathFreeObject(xptr);
  1613                      xmlXPathFreeContext(xptrctxt);
  1614                      xmlFree(URL);
  1615                      xmlFree(fragment);
  1616                      return(-1);
  1617                  }
  1618
  1619              case XPATH_RANGE:
  1620              case XPATH_LOCATIONSET:
  1621                  break;
  1622          }
  1623          set = xptr->nodesetval;
  1624          if (set != NULL) {
  1625              for (i = 0;i < set->nodeNr;i++) {
  1626                  if (set->nodeTab[i] == NULL)
  1627                      continue;
  1628                  switch (set->nodeTab[i]->type) {
  1629                      case XML_ELEMENT_NODE:
  1630                      case XML_TEXT_NODE:
  1631                      case XML_CDATA_SECTION_NODE:
  1632                      case XML_ENTITY_REF_NODE:
  1633                      case XML_ENTITY_NODE:
  1634                      case XML_PI_NODE:
  1635                      case XML_COMMENT_NODE:
  1636                      case XML_DOCUMENT_NODE:
  1637                      case XML_HTML_DOCUMENT_NODE:
  1638  #ifdef LIBXML_DOCB_ENABLED
  1639                      case XML_DOCB_DOCUMENT_NODE:
  1640  #endif
  1641                          continue;
  1642
  1643                      case XML_ATTRIBUTE_NODE:
  1644                          xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  1645                                         XML_XINCLUDE_XPTR_RESULT,
  1646                                         "XPointer selects an attribute: #%s\n",
  1647                                         fragment);
  1648                          set->nodeTab[i] = NULL;
  1649                          continue;
  1650                      case XML_NAMESPACE_DECL:
  1651                          xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  1652                                         XML_XINCLUDE_XPTR_RESULT,
  1653                                         "XPointer selects a namespace: #%s\n",
  1654                                         fragment);
  1655                          set->nodeTab[i] = NULL;
  1656                          continue;
  1657                      case XML_DOCUMENT_TYPE_NODE:
  1658                      case XML_DOCUMENT_FRAG_NODE:
  1659                      case XML_NOTATION_NODE:
  1660                      case XML_DTD_NODE:
  1661                      case XML_ELEMENT_DECL:
  1662                      case XML_ATTRIBUTE_DECL:
  1663                      case XML_ENTITY_DECL:
  1664                      case XML_XINCLUDE_START:
  1665                      case XML_XINCLUDE_END:
  1666                          xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  1667                                         XML_XINCLUDE_XPTR_RESULT,
  1668                                     "XPointer selects unexpected nodes: #%s\n",
  1669                                         fragment);
  1670                          set->nodeTab[i] = NULL;
  1671                          set->nodeTab[i] = NULL;
  1672                          continue; /* for */
  1673                  }
  1674              }
  1675          }
  1676          ctxt->incTab[nr]->inc =
  1677              xmlXIncludeCopyXPointer(ctxt, ctxt->doc, doc, xptr);
  1678          xmlXPathFreeObject(xptr);
  1679          xmlXPathFreeContext(xptrctxt);
  1680          xmlFree(fragment);
  1681      }
  1682  #endif
